CREATE FUNCTION public.validate_website_value() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(NEW.key)>120 OR length(NEW.value)>6000 THEN RAISE EXCEPTION 'Content is too long'; END IF; IF NEW.key IN ('contact.phone','contact.snack_phone') AND NEW.value !~ '^\+?[0-9 ()-]{10,25}$' THEN RAISE EXCEPTION 'Enter a valid phone number'; END IF; IF NEW.key LIKE '%.photo' OR NEW.key IN ('home.hero','home.how','home.league') THEN IF NEW.value <> '' AND NEW.value !~ '^https://' THEN RAISE EXCEPTION 'Use a secure image link'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_website_content BEFORE INSERT OR UPDATE ON public.website_content FOR EACH ROW EXECUTE FUNCTION public.validate_website_value();
CREATE TRIGGER validate_website_drafts BEFORE INSERT OR UPDATE ON public.website_drafts FOR EACH ROW EXECUTE FUNCTION public.validate_website_value();
CREATE FUNCTION public.validate_content_entry() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE v jsonb; BEGIN v=to_jsonb(NEW); IF v ? 'title' AND length(trim(v->>'title'))=0 THEN RAISE EXCEPTION 'Title is required'; END IF; IF v ? 'name' AND length(trim(v->>'name'))=0 THEN RAISE EXCEPTION 'Name is required'; END IF; IF v ? 'message' AND length(trim(v->>'message'))=0 THEN RAISE EXCEPTION 'Message is required'; END IF; IF v->>'start_date' IS NOT NULL AND v->>'end_date' IS NOT NULL AND (v->>'end_date')::date<(v->>'start_date')::date THEN RAISE EXCEPTION 'End date must be on or after start date'; END IF; IF v->>'starts_on' IS NOT NULL AND v->>'ends_on' IS NOT NULL AND (v->>'ends_on')::date<(v->>'starts_on')::date THEN RAISE EXCEPTION 'End date must be on or after start date'; END IF; IF v ? 'price' AND v->>'price' !~ '^\$?[0-9]+(\.[0-9]{1,2})?$' THEN RAISE EXCEPTION 'Enter a valid dollar amount'; END IF; IF coalesce(v->>'image_url','')<>'' AND v->>'image_url' !~ '^https://' THEN RAISE EXCEPTION 'Use a secure image link'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_events BEFORE INSERT OR UPDATE ON public.events FOR EACH ROW EXECUTE FUNCTION public.validate_content_entry();
CREATE TRIGGER validate_announcements BEFORE INSERT OR UPDATE ON public.announcements FOR EACH ROW EXECUTE FUNCTION public.validate_content_entry();
CREATE TRIGGER validate_prices BEFORE INSERT OR UPDATE ON public.pricing_items FOR EACH ROW EXECUTE FUNCTION public.validate_content_entry();
CREATE TRIGGER validate_menu BEFORE INSERT OR UPDATE ON public.menu_items FOR EACH ROW EXECUTE FUNCTION public.validate_content_entry();
CREATE TRIGGER validate_seasonal_schedule BEFORE INSERT OR UPDATE ON public.seasonal_hour_schedules FOR EACH ROW EXECUTE FUNCTION public.validate_content_entry();
CREATE FUNCTION public.website_special_schedule(p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE sid uuid; d jsonb; BEGIN IF NOT private.is_staff(auth.uid()) THEN RAISE EXCEPTION 'Staff only'; END IF; IF jsonb_array_length(p->'days')<>7 THEN RAISE EXCEPTION 'All seven days are required'; END IF; INSERT INTO public.seasonal_hour_schedules(title,date_label,reservation_notice,starts_on,ends_on,is_active) VALUES(p->>'title',p->>'date_label',p->>'reservation_notice',(p->>'starts_on')::date,(p->>'ends_on')::date,coalesce((p->>'is_active')::boolean,false)) RETURNING id INTO sid; FOR d IN SELECT value FROM jsonb_array_elements(p->'days') LOOP INSERT INTO public.seasonal_hours(schedule_id,day_of_week,day_label,food_service,bowler_hours,note) VALUES(sid,(d->>'day_of_week')::integer,d->>'day_label',d->>'food_service',d->>'bowler_hours',d->>'note'); END LOOP; RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.website_special_schedule(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.website_special_schedule(jsonb) TO authenticated;